/*
 * @module   rsq_unit
 * @brief    Reciprocal-sqrt unit of RMSNorm: the inverse-rms register from the ln lane's leading-one position and mantissa.
 * @details  GENERATED by tools/scripts/llama32_1b/gen_rom_sv.py from tools/models/vpu_ops.py (rsq_inv_mk); do not edit by hand.
 *           The shared tr_ln_alu receives the rounded mean mk = 2^k (1 + f) (RMSNorm mean, FRAC_W+LN_EXTRA = 6 fractional bits) and finds
 *           k (msb) and the normalized mantissa fraction f (fk, BITS bits) on its way to ln. Instead of the piecewise-linear ln, the
 *           exp, and the Q4.4 round trip between them, the inverse rms is read from a 64-entry table of 12-bit entries
 *           (one integer bit: entries < 2) indexed by {k & 1, top 5 bits of f}:
 *               entry = round(2^11 * c / sqrt(1 + (i + 1/2) / 2^5)),  c = 1 (even k) | sqrt(2) (odd k)
 *           and shifted right by (k + 1) >> 1 with one half-up rounding (round_shift(v, r) = (((2v) >> r) + 1) >> 1, shifter first).
 *           inv = round(2^(FW + INV_BITS + 3) / sqrt(mk)) = inverse rms in units of 2^-(FW + INV_BITS) per 1/16 code, as the apply
 *           multiplier expects. No cap is needed: the right shift keeps inv <= 2874 < 2^12.
 *           mk = 0 (ln short-circuit, msb = fk = 0) reads like mk = 1. Combinational.
 *           Bit-exact to tr_math_model.hpp::rms2_inv_mk and vpu_ops.rsq_inv_mk (verified by tb_soc/tr_rsq_unit over every reachable mk).
 *
 * @param    MSB_W   Width of msb (leading-one position of mk).
 * @param    BITS    Width of fk; the top 5 bits index the table (BITS >= 5).
 * @param    INV_W   Width of the inverse-rms register.
 */
module rsq_unit #(
    parameter int MSB_W = 4,
    parameter int BITS  = 6,
    parameter int INV_W = 12
)(
    input  logic [MSB_W-1:0] msb,
    input  logic [BITS-1:0]  fk,
    output logic [INV_W-1:0] inv
);

    function automatic logic [11:0] lookup(input logic [5:0] idx);
        case (idx)
            6'd0: lookup = 12'd2032;
            6'd1: lookup = 12'd2002;
            6'd2: lookup = 12'd1972;
            6'd3: lookup = 12'd1944;
            6'd4: lookup = 12'd1918;
            6'd5: lookup = 12'd1892;
            6'd6: lookup = 12'd1867;
            6'd7: lookup = 12'd1843;
            6'd8: lookup = 12'd1820;
            6'd9: lookup = 12'd1798;
            6'd10: lookup = 12'd1777;
            6'd11: lookup = 12'd1757;
            6'd12: lookup = 12'd1737;
            6'd13: lookup = 12'd1718;
            6'd14: lookup = 12'd1699;
            6'd15: lookup = 12'd1681;
            6'd16: lookup = 12'd1664;
            6'd17: lookup = 12'd1647;
            6'd18: lookup = 12'd1630;
            6'd19: lookup = 12'd1614;
            6'd20: lookup = 12'd1599;
            6'd21: lookup = 12'd1584;
            6'd22: lookup = 12'd1569;
            6'd23: lookup = 12'd1555;
            6'd24: lookup = 12'd1541;
            6'd25: lookup = 12'd1528;
            6'd26: lookup = 12'd1515;
            6'd27: lookup = 12'd1502;
            6'd28: lookup = 12'd1489;
            6'd29: lookup = 12'd1477;
            6'd30: lookup = 12'd1465;
            6'd31: lookup = 12'd1454;
            6'd32: lookup = 12'd2874;
            6'd33: lookup = 12'd2831;
            6'd34: lookup = 12'd2789;
            6'd35: lookup = 12'd2750;
            6'd36: lookup = 12'd2712;
            6'd37: lookup = 12'd2675;
            6'd38: lookup = 12'd2641;
            6'd39: lookup = 12'd2607;
            6'd40: lookup = 12'd2574;
            6'd41: lookup = 12'd2543;
            6'd42: lookup = 12'd2513;
            6'd43: lookup = 12'd2484;
            6'd44: lookup = 12'd2456;
            6'd45: lookup = 12'd2429;
            6'd46: lookup = 12'd2403;
            6'd47: lookup = 12'd2377;
            6'd48: lookup = 12'd2353;
            6'd49: lookup = 12'd2329;
            6'd50: lookup = 12'd2306;
            6'd51: lookup = 12'd2283;
            6'd52: lookup = 12'd2261;
            6'd53: lookup = 12'd2240;
            6'd54: lookup = 12'd2219;
            6'd55: lookup = 12'd2199;
            6'd56: lookup = 12'd2180;
            6'd57: lookup = 12'd2161;
            6'd58: lookup = 12'd2142;
            6'd59: lookup = 12'd2124;
            6'd60: lookup = 12'd2106;
            6'd61: lookup = 12'd2089;
            6'd62: lookup = 12'd2072;
            6'd63: lookup = 12'd2056;
            default: lookup = '0;
        endcase
    endfunction

    logic [5:0]      idx;
    logic [11:0]  v;
    logic [MSB_W:0]    msb1;                 // msb + 1
    logic [MSB_W-1:0]  r;                    // (msb + 1) >> 1
    logic [12:0]      z;                    // (2v) >> r
    logic [12:0]      rr;

    always_comb begin
        idx  = {msb[0], fk[BITS-1 -: 5]};
        v    = lookup(idx);
        msb1 = {1'b0, msb} + 1'b1;
        r    = msb1[MSB_W:1];
        z    = {v, 1'b0} >> r;
        rr   = (z + 1'b1) >> 1;
        inv  = INV_W'(rr);
    end

endmodule
